:root {
  --bg-base: #0a0a0a;
  --bg-surface: #111111;
  --bg-card: #1f1f1f;
  --border: #2a2a2a;
  --text: #fafafa;
  --text-muted: #a1a1aa;
  --accent: #0ea5e9;
  --success: #22c55e;
  --danger: #ef4444;
  --warning: #f59e0b;

  /* Uma cor por fonte de receita — a mesma em pílula, gráfico e avatar. */
  --src-empresa: #0ea5e9;
  --src-impressionart: #8b5cf6;
  --src-moto: #f59e0b;
  --src-mos: #22c55e;

  --fonte: 'Manrope', sans-serif;
  --fonte-titulo: 'Sora', sans-serif;
  --fonte-mono: 'JetBrains Mono', monospace;
}

body { background: var(--bg-base); color: var(--text); font-family: var(--fonte); }

/* Número em tabela, card ou badge nunca "dança" ao atualizar. */
.bs-num { font-variant-numeric: tabular-nums; }

body { display: flex; min-height: 100vh; }

.bs-side {
  position: sticky; top: 0;
  display: flex; flex-direction: column; flex-shrink: 0;
  width: 240px; height: 100vh;
  border-right: 1px solid var(--border); background: var(--bg-surface);
  /* Só a largura transiciona: animar o conteúdo junto embaralha o texto. */
  transition: width 0.2s ease;
}
.bs-side.bs-recolhida { width: 64px; }

.bs-side-topo {
  display: flex; align-items: center; gap: 10px;
  padding: 16px 12px 20px; border-bottom: 1px solid var(--border);
}
.bs-recolhida .bs-side-topo { flex-direction: column; gap: 8px; padding: 16px 8px 20px; }

.bs-side-logo {
  display: grid; place-items: center; flex-shrink: 0;
  width: 32px; height: 32px; border-radius: 8px;
  font-family: var(--fonte-titulo); font-size: 15px; font-weight: 700;
  color: var(--bg-base); background: var(--accent);
}
.bs-side-marca { font-family: var(--fonte-titulo); font-size: 14px; font-weight: 600; color: var(--text); }
.bs-side-link {
  margin-left: auto; padding: 6px; border-radius: 8px; color: var(--text-muted); line-height: 0;
}
.bs-recolhida .bs-side-link { margin-left: 0; }
.bs-side-link:hover { color: var(--text); background: var(--bg-card); }

.bs-side-nav { flex: 1; overflow-y: auto; padding: 12px; display: flex; flex-direction: column; gap: 16px; }
.bs-recolhida .bs-side-nav { padding: 12px 8px; }
.bs-side-nav::-webkit-scrollbar { display: none; }

.bs-side-titulo {
  margin-bottom: 6px; padding: 0 10px;
  font-size: 10px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.08em;
  color: var(--text-muted);
}
.bs-recolhida .bs-side-titulo { display: none; }

.bs-side-item {
  display: flex; align-items: center; gap: 10px; width: 100%;
  padding: 10px; border: none; border-radius: 8px;
  /* A barra existe em todo item, transparente quando inativo — se ela só
     nascesse no ativo, o texto andaria 2px a cada troca de tela. */
  border-left: 2px solid transparent;
  font-family: var(--fonte); font-size: 13px; font-weight: 500; text-align: left;
  color: var(--text-muted); background: transparent;
}
.bs-recolhida .bs-side-item { justify-content: center; padding: 10px 0; }
.bs-side-item:hover { color: var(--text); }
.bs-side-ativo {
  font-weight: 600; color: var(--text);
  background: var(--bg-card); border-left-color: var(--accent);
}
.bs-side-perigo { color: var(--danger); }

.bs-side-icwrap { position: relative; display: flex; flex-shrink: 0; }
.bs-side-ic { width: 16px; height: 16px; }
.bs-side-rotulo { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.bs-recolhida .bs-side-rotulo { display: none; }

.bs-side-badge {
  flex-shrink: 0; padding: 1px 6px; border-radius: 999px;
  font-size: 10px; font-weight: 700; color: var(--bg-base); background: var(--accent);
}
.bs-recolhida .bs-side-badge { display: none; }

/* Recolhida, o número não cabe: a pendência vira um ponto sobre o ícone. */
.bs-side-ponto {
  display: none; position: absolute; top: -3px; right: -3px;
  width: 8px; height: 8px; border-radius: 999px; background: var(--accent);
}
.bs-recolhida .bs-side-ponto { display: block; }

.bs-side-user {
  display: flex; align-items: center; gap: 10px;
  padding: 12px; border-top: 1px solid var(--border);
}
.bs-recolhida .bs-side-user { justify-content: center; }
.bs-side-avatar {
  display: grid; place-items: center; flex-shrink: 0;
  width: 32px; height: 32px; border-radius: 8px;
  font-family: var(--fonte-titulo); font-size: 12px; font-weight: 700;
  color: var(--text); background: var(--bg-card);
}
.bs-side-userinfo { min-width: 0; }
.bs-recolhida .bs-side-userinfo { display: none; }
.bs-side-username {
  font-size: 12px; font-weight: 600; color: var(--text);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.bs-side-userrole { font-size: 10px; color: var(--text-muted); }

.bs-side-toggle {
  display: flex; align-items: center; justify-content: center;
  padding: 10px; border: none; border-top: 1px solid var(--border);
  color: var(--text-muted); background: transparent;
}
.bs-side-toggle:hover { color: var(--text); }
.bs-recolhida .bs-side-toggle svg { transform: rotate(180deg); }

